<template>
  <section class="story-workbench">
    <header class="story-header">
      <div><span class="eyebrow">故事图谱</span><h2>原文证据与生产事件</h2><p>章节是证据，只有已确认事件才能进入生产上下文。</p></div>
      <nav><button type="button" :class="{ active: mode === 'reader' }" @click="mode = 'reader'"><BookOpenText :size="14" />原文阅读</button><button type="button" :class="{ active: mode === 'graph' }" @click="mode = 'graph'"><GitBranch :size="14" />事件图</button></nav>
      <div class="story-actions"><select v-model="contextItemId"><option value="">选择生产节点</option><option v-for="item in productionItems" :key="item.id" :value="item.id">EP{{ pad(item.episode) }} · {{ item.title }}</option></select><button type="button" :disabled="!contextItemId" @click="previewContext"><ScanText :size="14" />生产上下文</button><button type="button" class="import-action" @click="showImport = true"><FileInput :size="14" />导入原文</button></div>
    </header>

    <div class="story-body">
      <aside class="chapter-rail">
        <header><span>原文来源</span><b>{{ sources.length }}</b></header>
        <button v-for="source in sources" :key="source.id" type="button" class="source-row" :class="{ active: activeSourceId === source.id }" @click="selectSource(source.id)"><i>{{ source.kind === 'docx' ? 'W' : source.kind === 'markdown' ? 'M' : 'T' }}</i><div><b>{{ source.title }}</b><span>{{ formatNumber(source.charCount) }} 字 · r{{ source.revision }}</span><small>{{ source.originalPath }}</small></div></button>
        <div v-if="!sources.length" class="rail-empty">尚未导入原文</div>
        <section class="chapter-list"><header><span>章节</span><b>{{ sourceChapters.length }}</b></header><button v-for="chapter in sourceChapters" :key="chapter.id" type="button" :class="{ active: activeChapterId === chapter.id }" @click="selectChapter(chapter.id)"><span>{{ String(chapter.index).padStart(2,'0') }}</span><div><b>{{ chapter.title }}</b><small>{{ formatNumber(chapter.charCount) }} 字 · {{ chapterEventCount(chapter.id) }} 事件</small></div></button></section>
      </aside>

      <main v-if="mode === 'reader'" class="chapter-reader">
        <div v-if="!activeChapter" class="story-empty"><BookOpenText :size="30" /><span>导入 TXT、Markdown 或 DOCX 后开始建立故事证据。</span></div>
        <template v-else>
          <header><div><span>第 {{ activeChapter.index }} 章</span><h3>{{ activeChapter.title }}</h3><p>{{ activeChapter.path }}</p></div><label><Search :size="13" /><input v-model="readerQuery" placeholder="在本章查找" /><b>{{ readerMatches || '' }}</b></label></header>
          <article ref="readerElement" class="reader-paper">{{ chapterContent?.content }}</article>
          <footer><span>快照哈希 {{ activeChapter.sha256.slice(0,12) }}</span><span>{{ formatNumber(activeChapter.charCount) }} 字</span><span>r{{ activeChapter.revision }}</span></footer>
        </template>
      </main>

      <main v-else class="event-graph">
        <div v-if="!events.length" class="story-empty"><GitBranch :size="30" /><span>当前没有故事事件；先从章节右侧创建草稿事件。</span></div>
        <VueFlow v-else :nodes="graphNodes" :edges="graphEdges" :fit-view-on-init="true" :min-zoom="0.18" :max-zoom="1.7" :nodes-draggable="true" :nodes-connectable="true" @node-click="onGraphNode" @connect="onGraphConnect"><Background pattern-color="#292b27" :gap="24" :size="1" /><Controls position="bottom-left"><template #icon-zoom-in><Plus :size="14" aria-hidden="true" /><span class="sr-only">放大事件图</span></template><template #icon-zoom-out><Minus :size="14" aria-hidden="true" /><span class="sr-only">缩小事件图</span></template><template #icon-fit-view><Scan :size="14" aria-hidden="true" /><span class="sr-only">适配全部事件</span></template><template #icon-unlock><LockOpen :size="14" aria-hidden="true" /><span class="sr-only">锁定事件图交互</span></template><template #icon-lock><Lock :size="14" aria-hidden="true" /><span class="sr-only">启用事件图交互</span></template></Controls></VueFlow>
        <div class="graph-legend"><span><i class="draft"></i>草稿</span><span><i class="confirmed"></i>已确认</span><span><i class="deprecated"></i>弃用</span><em>连线方向：前置事件 → 后续事件</em></div>
      </main>

      <aside class="event-inspector">
        <header><div><span>{{ activeChapter ? activeChapter.title : '事件检查器' }}</span><b>{{ chapterEvents.length }} 个事件</b></div><button type="button" :disabled="!activeChapter" @click="newEvent"><Plus :size="14" /> 新建</button></header>
        <div class="event-strip"><button v-for="event in chapterEvents" :key="event.id" type="button" :class="{ active: eventDraft.id === event.id }" @click="selectEvent(event)"><i :class="event.status"></i><div><span>#{{ event.order }} · {{ eventStatusLabel(event.status) }}</span><b>{{ event.title }}</b><small>{{ event.description }}</small></div></button><p v-if="!chapterEvents.length">本章尚无事件</p></div>
        <div class="event-editor" :class="{ disabled: !activeChapter }">
          <div class="event-meta"><label><span>状态</span><select v-model="eventDraft.status"><option value="draft">草稿</option><option value="confirmed">已确认</option><option value="deprecated">弃用</option></select></label><label><span>顺序</span><input v-model.number="eventDraft.order" type="number" min="1" /></label></div>
          <label><span>事件标题</span><input v-model="eventDraft.title" /></label>
          <label><span>事件描述</span><textarea v-model="eventDraft.description" rows="5"></textarea></label>
          <label><span>原文证据</span><textarea v-model="eventDraft.sourceExcerpt" rows="4" placeholder="粘贴能够证明事件的原文句段"></textarea><button type="button" class="selection-action" @click="useSelection"><TextSelect :size="12" /> 使用当前选中文本</button></label>
          <div class="entity-grid"><label><span>角色</span><input v-model="eventDraft.charactersText" /></label><label><span>场景</span><input v-model="eventDraft.locationsText" /></label><label><span>道具</span><input v-model="eventDraft.propsText" /></label><label><span>标签</span><input v-model="eventDraft.tagsText" /></label></div>
          <div class="event-meta"><label><span>集数</span><input v-model.number="eventDraft.episode" type="number" min="1" /></label><label><span>15 秒编号</span><input v-model.number="eventDraft.unit" type="number" min="1" /></label></div>
          <label><span>关联生产节点 ID</span><textarea v-model="eventDraft.itemIdsText" rows="3"></textarea></label>
          <label><span>前置事件 ID</span><textarea v-model="eventDraft.dependenciesText" rows="3"></textarea></label>
          <button type="button" class="save-event" :disabled="savingEvent || !activeChapter || !eventDraft.title.trim()" @click="saveEvent"><Save :size="14" /> {{ savingEvent ? '保存中' : eventDraft.status === 'confirmed' ? '保存已确认事件' : '保存事件草稿' }}</button>
        </div>
      </aside>
    </div>

    <div v-if="showImport" class="story-overlay" @click.self="showImport = false"><section class="import-dialog"><header><div><span class="eyebrow">原文入库</span><h3>导入章节证据</h3></div><button type="button" aria-label="关闭原文导入" @click="showImport = false"><X :size="16" /></button></header><nav><button type="button" :class="{active:importMode==='file'}" @click="importMode='file'">本地文件</button><button type="button" :class="{active:importMode==='paste'}" @click="importMode='paste'">粘贴文本</button></nav><div class="import-form"><label><span>标题</span><input v-model="importTitle" placeholder="例如：黄金面具第一卷" /></label><template v-if="importMode==='file'"><button type="button" class="file-picker" @click="pickSource"><FileText :size="20" /><div><b>{{ importPath ? basename(importPath) : '选择 TXT / Markdown / DOCX' }}</b><small>{{ importPath || '原文件保持原位，画布只保存文本快照。' }}</small></div></button></template><label v-else><span>原文内容</span><textarea v-model="pasteContent" rows="16" placeholder="粘贴小说、剧本或补充原文。"></textarea></label></div><footer><button type="button" @click="showImport=false">取消</button><button type="button" class="primary-import" :disabled="importing || !importTitle.trim() || (importMode==='file' ? !importPath : !pasteContent.trim())" @click="runImport"><FileInput :size="14" />{{ importing ? '正在拆章' : '导入并拆章' }}</button></footer></section></div>

    <div v-if="storyContext" class="story-overlay" @click.self="storyContext = null"><section class="context-dialog"><header><div><span class="eyebrow">生产上下文</span><h3>{{ storyContext.item.title }}</h3></div><div><button type="button" @click="copyContext"><Copy :size="13" /> {{ contextCopied ? '已复制' : '复制' }}</button><button type="button" aria-label="关闭生产上下文" @click="storyContext=null"><X :size="16" /></button></div></header><div class="context-facts"><span>{{ storyContext.events.length }} 个确认事件</span><span>{{ storyContext.chapterExcerpts.length }} 章原文证据</span><span>{{ storyContext.hardLocks.length }} 个硬锁</span></div><pre>{{ storyContext.prompt }}</pre></section></div>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from "vue";
import { Background } from "@vue-flow/background";
import { Controls } from "@vue-flow/controls";
import { VueFlow, type Connection, type Edge, type Node, type NodeMouseEvent } from "@vue-flow/core";
import { BookOpenText, Copy, FileInput, FileText, GitBranch, Lock, LockOpen, Minus, Plus, Save, Scan, ScanText, Search, TextSelect, X } from "lucide-vue-next";
import type { ProjectIndex, StoryChapter, StoryChapterContent, StoryContextBundle, StoryEvent, StoryEventStatus, StorySource } from "@core/types";

const props=defineProps<{projectRoot:string;index:ProjectIndex}>();
const emit=defineEmits<{changed:[message:string];failed:[message:string]}>();
const mode=ref<"reader"|"graph">("reader");const sources=ref<StorySource[]>([]);const chapters=ref<StoryChapter[]>([]);const events=ref<StoryEvent[]>([]);const activeSourceId=ref("");const activeChapterId=ref("");const chapterContent=ref<StoryChapterContent|null>(null);const readerQuery=ref("");const readerElement=ref<HTMLElement|null>(null);const showImport=ref(false);const importMode=ref<"file"|"paste">("file");const importPath=ref("");const importTitle=ref("");const pasteContent=ref("");const importing=ref(false);const savingEvent=ref(false);const contextItemId=ref("");const storyContext=ref<StoryContextBundle|null>(null);const contextCopied=ref(false);
type EventDraft={id?:string;chapterId:string;order:number;title:string;description:string;sourceExcerpt:string;charactersText:string;locationsText:string;propsText:string;tagsText:string;episode?:number;unit?:number;itemIdsText:string;dependenciesText:string;status:StoryEventStatus;revision?:number};
const eventDraft=reactive<EventDraft>(emptyEvent());
const activeChapter=computed(()=>chapters.value.find(chapter=>chapter.id===activeChapterId.value));const sourceChapters=computed(()=>chapters.value.filter(chapter=>chapter.sourceId===activeSourceId.value).sort((a,b)=>a.index-b.index));const chapterEvents=computed(()=>events.value.filter(event=>event.chapterId===activeChapterId.value).sort((a,b)=>a.order-b.order));const productionItems=computed(()=>props.index.items.filter(item=>item.type==="unit").sort((a,b)=>(a.episode??0)-(b.episode??0)||(a.unit??0)-(b.unit??0)));const readerMatches=computed(()=>{const q=readerQuery.value.trim();return q&&chapterContent.value?(chapterContent.value.content.toLowerCase().split(q.toLowerCase()).length-1):0;});
const chapterOrder=computed(()=>new Map(chapters.value.map((chapter,index)=>[chapter.id,index])));const graphNodes=computed<Node[]>(()=>events.value.map(event=>({id:event.id,type:"default",position:{x:(chapterOrder.value.get(event.chapterId)??0)*330,y:Math.max(0,event.order-1)*150},label:`${event.status==="confirmed"?"已确认":event.status==="draft"?"草稿":"弃用"}\n${event.title}`,class:`story-event-node event-${event.status}`,data:{event}})));const graphEdges=computed<Edge[]>(()=>events.value.flatMap(event=>event.dependencyIds.map(source=>({id:`story-${source}-${event.id}`,source,target:event.id,animated:event.status==="confirmed",class:"story-event-edge"}))));
onMounted(()=>void loadAll());
async function loadAll(preferredSource?:string){try{const[nextSources,nextChapters,nextEvents]=await Promise.all([window.canvasApi.listStorySources(props.projectRoot),window.canvasApi.listStoryChapters(props.projectRoot),window.canvasApi.listStoryEvents(props.projectRoot,{includeOrphans:true})]);sources.value=nextSources;chapters.value=nextChapters;events.value=nextEvents;if(preferredSource)activeSourceId.value=preferredSource;if(!sources.value.some(source=>source.id===activeSourceId.value))activeSourceId.value=sources.value[0]?.id??"";if(!sourceChapters.value.some(chapter=>chapter.id===activeChapterId.value))activeChapterId.value=sourceChapters.value[0]?.id??"";await loadChapter();if(!eventDraft.id&&chapterEvents.value[0])selectEvent(chapterEvents.value[0]);}catch(error){emit("failed",message(error));}}
async function selectSource(id:string){activeSourceId.value=id;activeChapterId.value=sourceChapters.value[0]?.id??"";await loadChapter();newEvent();}
async function selectChapter(id:string){activeChapterId.value=id;await loadChapter();const first=chapterEvents.value[0];if(first)selectEvent(first);else newEvent();}
async function loadChapter(){chapterContent.value=activeChapterId.value?await window.canvasApi.readStoryChapter(props.projectRoot,activeChapterId.value):null;}
function emptyEvent():EventDraft{return{chapterId:activeChapterId?.value??"",order:1,title:"",description:"",sourceExcerpt:"",charactersText:"",locationsText:"",propsText:"",tagsText:"",itemIdsText:"",dependenciesText:"",status:"draft"};}
function newEvent(){Object.assign(eventDraft,{...emptyEvent(),chapterId:activeChapterId.value,order:chapterEvents.value.length+1});}
function selectEvent(event:StoryEvent){activeChapterId.value=event.chapterId;activeSourceId.value=chapters.value.find(chapter=>chapter.id===event.chapterId)?.sourceId??activeSourceId.value;Object.assign(eventDraft,{id:event.id,chapterId:event.chapterId,order:event.order,title:event.title,description:event.description,sourceExcerpt:event.sourceExcerpt??"",charactersText:event.characters.join("、"),locationsText:event.locations.join("、"),propsText:event.props.join("、"),tagsText:event.tags.join("、"),episode:event.episode,unit:event.unit,itemIdsText:event.itemIds.join("\n"),dependenciesText:event.dependencyIds.join("\n"),status:event.status,revision:event.revision});void loadChapter();}
async function saveEvent(){if(!activeChapter.value)return;savingEvent.value=true;try{const saved=await window.canvasApi.upsertStoryEvent(props.projectRoot,{id:eventDraft.id,chapterId:activeChapter.value.id,order:eventDraft.order,title:eventDraft.title,description:eventDraft.description,sourceExcerpt:eventDraft.sourceExcerpt||undefined,characters:list(eventDraft.charactersText),locations:list(eventDraft.locationsText),props:list(eventDraft.propsText),tags:list(eventDraft.tagsText),episode:eventDraft.episode||undefined,unit:eventDraft.unit||undefined,itemIds:lines(eventDraft.itemIdsText),dependencyIds:lines(eventDraft.dependenciesText),status:eventDraft.status,expectedRevision:eventDraft.revision});events.value=await window.canvasApi.listStoryEvents(props.projectRoot,{includeOrphans:true});selectEvent(saved);emit("changed",`故事事件已保存：${saved.title} · ${eventStatusLabel(saved.status)}`);}catch(error){emit("failed",message(error));}finally{savingEvent.value=false;}}
async function onGraphConnect(connection:Connection){if(!connection.source||!connection.target)return;try{const updated=await window.canvasApi.connectStoryEvents(props.projectRoot,connection.source,connection.target);events.value=await window.canvasApi.listStoryEvents(props.projectRoot,{includeOrphans:true});selectEvent(updated);emit("changed","事件依赖已建立");}catch(error){emit("failed",message(error));}}
function onGraphNode(event:NodeMouseEvent){const storyEvent=events.value.find(item=>item.id===event.node.id);if(storyEvent)selectEvent(storyEvent);}
function useSelection(){const value=window.getSelection()?.toString().trim();if(value)eventDraft.sourceExcerpt=value.slice(0,8000);else emit("failed","请先在章节正文中选择原文句段");}
async function pickSource(){const file=await window.canvasApi.pickStorySource();if(file){importPath.value=file;if(!importTitle.value)importTitle.value=basename(file).replace(/\.(txt|md|markdown|docx)$/i,"");}}
async function runImport(){importing.value=true;try{const result=importMode.value==="file"?await window.canvasApi.importStoryFile(props.projectRoot,importPath.value,importTitle.value):await window.canvasApi.importStoryText(props.projectRoot,{title:importTitle.value,content:pasteContent.value,kind:"markdown"});showImport.value=false;await loadAll(result.source.id);emit("changed",`原文已导入：${result.chapters.length} 章${result.warnings.length?`；${result.warnings.join("；")}`:""}`);}catch(error){emit("failed",message(error));}finally{importing.value=false;}}
async function previewContext(){if(!contextItemId.value)return;try{storyContext.value=await window.canvasApi.buildStoryContext(props.projectRoot,contextItemId.value);}catch(error){emit("failed",message(error));}}
async function copyContext(){if(!storyContext.value)return;await window.canvasApi.copyText(storyContext.value.prompt);contextCopied.value=true;setTimeout(()=>contextCopied.value=false,1500);}
function list(value:string){return value.split(/、|,|，|\n/).map(v=>v.trim()).filter(Boolean);}function lines(value:string){return value.split("\n").map(v=>v.trim()).filter(Boolean);}function chapterEventCount(id:string){return events.value.filter(event=>event.chapterId===id).length;}function eventStatusLabel(status:StoryEventStatus){return({draft:"草稿",confirmed:"已确认",deprecated:"弃用"})[status];}function pad(value?:number,length=2){return String(value??0).padStart(length,"0");}function formatNumber(value:number){return new Intl.NumberFormat("zh-CN").format(value);}function basename(value:string){return value.split("/").filter(Boolean).at(-1)??value;}function message(error:unknown){return error instanceof Error?error.message:String(error);}
</script>

<style scoped>
.story-workbench{height:100%;display:grid;grid-template-rows:84px minmax(0,1fr);background:#10110e}.story-header{display:grid;grid-template-columns:minmax(280px,1fr) auto minmax(390px,1fr);align-items:center;padding:0 22px;border-bottom:1px solid #30322c;background:#151613}.story-header h2{margin:6px 0 3px;font-size:18px}.story-header p{margin:0;color:#6e7168;font-size:8px}.story-header nav{display:flex;align-self:end;height:42px}.story-header nav button{display:flex;align-items:center;gap:6px;padding:0 15px;border:0;border-bottom:2px solid transparent;background:transparent;color:#777a70;font-size:8px}.story-header nav button.active{border-bottom-color:#d7af55;color:#d7af55}.story-actions{display:flex;justify-content:flex-end;gap:6px}.story-actions select,.story-actions button{height:30px;border:1px solid #373931;background:transparent;color:#999c92;font-size:8px}.story-actions select{max-width:180px;padding:0 7px;background:#181916}.story-actions button{display:flex;align-items:center;gap:5px;padding:0 9px}.story-actions .import-action{border-color:#d7af55;background:#d7af55;color:#17130a;font-weight:700}.story-body{min-height:0;display:grid;grid-template-columns:250px minmax(0,1fr) 370px}.chapter-rail{min-height:0;overflow:auto;border-right:1px solid #30322c;background:#151613}.chapter-rail>header,.chapter-list>header{height:43px;display:flex;align-items:center;justify-content:space-between;padding:0 12px;border-bottom:1px solid #2d2f29;color:#85887d;font-size:8px}.source-row{width:100%;display:grid;grid-template-columns:28px 1fr;gap:9px;padding:12px;border:0;border-bottom:1px solid #292b25;border-left:2px solid transparent;background:transparent;color:#bbb;text-align:left}.source-row.active{border-left-color:#d7af55;background:#202019}.source-row>i{width:24px;height:28px;display:grid;place-items:center;border:1px solid #4a4c43;color:#d7af55;font:8px Menlo,monospace;font-style:normal}.source-row b,.source-row span,.source-row small{display:block}.source-row b{fon